-- PELPA backend. Safe to run more than once. Paste into Supabase > SQL Editor > Run.
create table if not exists admins(email text primary key);
insert into admins(email) values ('sonamdorji11914000599@gmail.com') on conflict do nothing;
create or replace function is_admin() returns boolean language sql security definer stable set search_path=public as $$ select exists(select 1 from admins where lower(email)=lower(auth.jwt()->>'email')) $$;
create table if not exists settings(key text primary key,value jsonb);
create table if not exists members(id uuid primary key default gen_random_uuid(),role text,name text,years int,languages text,bio text,photo text,status text default 'pending',phone text,license_no text);
create table if not exists reviews(id uuid primary key default gen_random_uuid(),member_id uuid,stars int,reviewer text,booking_ref text,comment text,resolved boolean default false,created_at timestamptz default now());
create table if not exists packages(id text primary key,name text,cat text,days int,price numeric,region text,blurb text,highlights text[]);
alter table packages add column if not exists itin text, add column if not exists premier boolean default false, add column if not exists published boolean default true, add column if not exists image text;
create table if not exists bookings(id uuid primary key default gen_random_uuid(),package_id text,guest_name text,email text,phone text,travel_date date,guests int,total numeric,method text,status text,verified boolean,created_at timestamptz default now());
alter table bookings add column if not exists ref text, add column if not exists pay_reference text, add column if not exists amount_due numeric, add column if not exists paid_usd numeric default 0, add column if not exists guide_id text, add column if not exists driver_id text, add column if not exists admin_notes text;
create unique index if not exists bookings_ref_u on bookings(ref);
create table if not exists enquiries(id uuid primary key default gen_random_uuid(),name text,email text,phone text,message text,created_at timestamptz default now());
create table if not exists inquiries(id uuid primary key default gen_random_uuid(),name text,email text,phone text,message text,created_at timestamptz default now());
create or replace view member_stats as select member_id,avg(stars)::numeric(3,2) avg,count(*) n from reviews group by member_id;
do $$ declare t text; begin foreach t in array array['admins','settings','members','reviews','packages','bookings','enquiries','inquiries'] loop execute format('alter table %I enable row level security',t); execute format('drop policy if exists admin_all on %I',t); execute format('create policy admin_all on %I for all using (is_admin()) with check (is_admin())',t); end loop; end $$;
drop policy if exists pub_read on settings; create policy pub_read on settings for select using (true);
drop policy if exists pub_read on packages; create policy pub_read on packages for select using (coalesce(published,true));
drop policy if exists pub_read on members; create policy pub_read on members for select using (status='approved');
drop policy if exists pub_read on reviews; create policy pub_read on reviews for select using (true);
drop policy if exists pub_ins on bookings; create policy pub_ins on bookings for insert with check (true);
drop policy if exists pub_ins on enquiries; create policy pub_ins on enquiries for insert with check (true);
drop policy if exists pub_ins on inquiries; create policy pub_ins on inquiries for insert with check (true);
drop policy if exists pub_ins on reviews; create policy pub_ins on reviews for insert with check (stars between 1 and 5);
drop policy if exists pub_ins on members; create policy pub_ins on members for insert with check (status='pending');
create or replace function get_booking(p_ref text, p_email text) returns table(ref text,guest_name text,package_id text,travel_date date,guests int,total numeric,status text,paid_usd numeric,guide_id text,driver_id text) language sql security definer set search_path=public as $$ select b.ref,b.guest_name,b.package_id,b.travel_date,b.guests,b.total,b.status,b.paid_usd,b.guide_id,b.driver_id from bookings b where b.ref=p_ref and lower(b.email)=lower(p_email) $$;
grant execute on function get_booking(text,text) to anon;
grant select on member_stats to anon;
insert into storage.buckets(id,name,public) values ('site','site',true) on conflict do nothing;
drop policy if exists site_read on storage.objects; create policy site_read on storage.objects for select using (bucket_id='site');
drop policy if exists site_write on storage.objects; create policy site_write on storage.objects for all using (bucket_id='site' and is_admin()) with check (bucket_id='site' and is_admin());
